DECLARE
  v_sal EMP.SAL%TYPE;
  v_annual NUMBER;
BEGIN
  SELECT SAL INTO v_sal FROM EMP WHERE ENAME = 'FORD';
  v_annual := v_sal * 12;
  DBMS_OUTPUT.PUT_LINE('Ford Annual Salary: ' || v_annual);
END;

