DECLARE
  v_rec EMP%ROWTYPE;
BEGIN
  SELECT * INTO v_rec FROM EMP WHERE EMPNO = 7839;
  DBMS_OUTPUT.PUT_LINE(v_rec.empno || ' ' || v_rec.ename || ' ' || v_rec.job || ' ' || v_rec.sal || ' ' || v_rec.deptno);
END;

DECLARE
  v_emp EMP%ROWTYPE;
BEGIN
  SELECT * INTO v_emp FROM EMP WHERE ENAME = 'SCOTT';
  DBMS_OUTPUT.PUT_LINE('Name: ' || v_emp.ename);
  DBMS_OUTPUT.PUT_LINE('Salary: ' || v_emp.sal);
  DBMS_OUTPUT.PUT_LINE('Job: ' || v_emp.job);
END;

DECLARE
  v_rec EMP%ROWTYPE;
BEGIN
  SELECT * INTO v_rec FROM EMP WHERE ENAME = 'SMITH';
  v_rec.sal := v_rec.sal + 500;
  DBMS_OUTPUT.PUT_LINE('Updated Salary for ' || v_rec.ename || ': ' || v_rec.sal);
END;

DECLARE
  v_row EMP%ROWTYPE;
BEGIN
  SELECT * INTO v_row FROM EMP WHERE ROWNUM = 1;
  DBMS_OUTPUT.PUT_LINE('First Row Data: ' || v_row.ename || ' - ' || v_row.job);
END;
